//! Conservative DAV request boundary. This subset is intentionally not a
//! complete RFC 4918 If parser. Unsupported conditions never authorize writes.
use crate::{LockError, LockRegistry};
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DavRequestError {
    UnsupportedCondition,
    PreconditionFailed,
    Lock(LockError),
}

impl From<LockError> for DavRequestError {
    fn from(error: LockError) -> Self {
        Self::Lock(error)
    }
}

/// Only tokens generated by the existing registry are accepted. No URI
/// percent decoding or whitespace folding of the token itself is performed.
pub fn parse_lock_token_header(header: &str) -> Result<&str, DavRequestError> {
    let token = header.trim_matches([' ', '\t'])
        .strip_prefix('<')
        .and_then(|value| value.strip_suffix('>'))
        .ok_or(DavRequestError::UnsupportedCondition)?;
    let value = token.strip_prefix("opaquelocktoken:")
        .ok_or(DavRequestError::UnsupportedCondition)?;
    if value.len() != 32 || !value.bytes().all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b)) {
        return Err(DavRequestError::UnsupportedCondition);
    }
    Ok(token)
}

fn parse_if(header: &str) -> Result<&str, DavRequestError> {
    let inner = header.trim_matches([' ', '\t'])
        .strip_prefix('(')
        .and_then(|value| value.strip_suffix(')'))
        .ok_or(DavRequestError::UnsupportedCondition)?;
    parse_lock_token_header(inner)
}

impl LockRegistry {
    /// The HTTP caller must authenticate the request, canonicalize the path,
    /// reject duplicate header fields and serialize all namespace mutations.
    /// A supplied positive condition must apply even to an unlocked resource.
    pub fn with_dav_if<T>(
        &mut self,
        now: Instant,
        path: &str,
        recursive: bool,
        condition: Option<&str>,
        mutation: impl FnOnce() -> T,
    ) -> Result<T, DavRequestError> {
        let token = condition.map(parse_if).transpose()?;
        if let Some(token) = token {
            if !self.token_applies(now, path, token)? {
                return Err(DavRequestError::PreconditionFailed);
            }
            self.with_mutation(now, &[(path, recursive)], &[token], mutation)
                .map_err(|error| match error {
                    LockError::Conflict => DavRequestError::PreconditionFailed,
                    other => other.into(),
                })
        } else {
            self.with_mutation(now, &[(path, recursive)], &[], mutation)
                .map_err(Into::into)
        }
    }

    pub fn refresh_dav(
        &mut self,
        now: Instant,
        path: &str,
        condition: &str,
        ttl: Duration,
    ) -> Result<(), DavRequestError> {
        let token = parse_if(condition)?;
        self.refresh(now, path, token, ttl).map_err(Into::into)
    }

    pub fn unlock_dav(
        &mut self,
        now: Instant,
        path: &str,
        header: &str,
    ) -> Result<(), DavRequestError> {
        let token = parse_lock_token_header(header)?;
        self.unlock(now, path, token).map_err(Into::into)
    }
}
